export QA_BASE=http://127.0.0.1:8098
RIGHT="rectangle ke chaaron sides jodenge, 50 plus 30 plus 50 plus 30, 160 metre"
endrun(){ timeout 2400 env QA_ACC="$1" QA_TAG="$2" QA_TOPIC="$3" QA_LINES="$4" node $S/end.mjs 2>&1 | tail -1 | tee $Q/$2.json | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{try{const j=JSON.parse(s);console.log("== "+j.tag+" lesson "+j.lessonId+" end="+j.end.status+" export="+j.export.status);for(const t of j.turns)console.log(" t"+t.i+" ["+String(t.line).slice(0,50)+"] move="+t.move+" sheet="+t.sheet+" HELPLINE="+t.helpline);console.log(" SUMMARY: "+JSON.stringify(j.record.summary));console.log(" NOTE: "+JSON.stringify(j.record.parentNote));console.log(" EXPORT same="+(j.record.exportSummary===j.record.summary&&j.record.exportNote===j.record.parentNote)+" conversation="+JSON.stringify(j.record.exportConversation).slice(0,200)+" remembered="+JSON.stringify(j.record.remembered).slice(0,150));console.log(" CHECKS "+JSON.stringify(j.checks))}catch(e){console.log("PARSE FAIL "+s.slice(0,300))}})'; src $2; }
agrun(){ echo "== $2"; timeout 1800 env QA_ACC="$1" QA_TOPIC="$3" QA_RULES="$4" QA_TURNS="${5:-10}" node $S/ag.mjs 2>&1 | tail -1 | tee $Q/$2.json | cut -c1-1500; }
# per server turn: the child's words, the move (with item), and the classify verdict (the grading source)
cls(){ id=$(grep -oE '"lesson(Id)?":"[0-9a-f-]{36}"' $Q/$1.json | head -1 | cut -d'"' -f4); [ -n "$id" ] && TAXILA_DB=test timeout 150 node --env-file=.env.local scripts/trace.mjs --session $id 2>&1 | grep -E "CHILD →|TURN [0-9]+ move|classify .* verdict|safety distress|studio\.(board|slot|picture)|picture|board_failed|slot failed" | grep -vE "model .* chat|perf\." | sed -E 's/^[0-9:.]+ //' | cut -c1-230; }
